import { useEffect, useRef, useState, createContext, useContext } from 'react'
import { BrowserRouter, Routes, Route, Navigate, Link, NavLink, useLocation, useNavigate, useParams, useSearchParams } from 'react-router-dom'
import { Activity, ArrowLeft, ArrowRight, BriefcaseBusiness, Check, ChevronDown, CircleAlert, ClipboardList, FileText, Gauge, LayoutDashboard, LogOut, Menu, MoreHorizontal, Search, Settings, ShieldCheck, Sparkles, Target, TrendingUp, UploadCloud, UserRound, Users, X, Zap } from 'lucide-react'
import { AreaChart, Area, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts'
import { useAuth } from './context/AuthContext'
import { apiError, adminApi, attritionApi, employeesApi, jobsApi, matchApi, pageContent, profileApi, resumeApi } from './lib/api'
import { ApplicationsPage, LiveAdminActivity, LiveAdminUsers, LiveAttritionDashboard, LiveJobListings, LiveMatchPage, LiveRankedCandidates } from './LiveFeatures'

const ToastContext = createContext(() => {})
const useToast = () => useContext(ToastContext)
const cn = (...classes) => classes.filter(Boolean).join(' ')
const sampleJobs = [
  { id: 'job-1', title: 'Senior Product Designer', company: 'Northstar Labs', location: 'Toronto · Hybrid', type: 'Full-time', salary: '$125k – $145k', matchScore: 94, tags: ['Figma', 'Design systems', 'Research'] },
  { id: 'job-2', title: 'Product Designer II', company: 'Lattice', location: 'Remote · Canada', type: 'Full-time', salary: '$110k – $132k', matchScore: 89, tags: ['Prototyping', 'UX strategy', 'B2B'] },
  { id: 'job-3', title: 'UX Designer', company: 'Mosaic Health', location: 'Vancouver · Hybrid', type: 'Full-time', salary: '$98k – $118k', matchScore: 82, tags: ['Healthcare', 'Usability', 'Figma'] },
]
