const chartData = [{ name: 'Jan', hires: 19, apps: 96 }, { name: 'Feb', hires: 24, apps: 112 }, { name: 'Mar', hires: 28, apps: 138 }, { name: 'Apr', hires: 22, apps: 129 }, { name: 'May', hires: 35, apps: 166 }, { name: 'Jun', hires: 31, apps: 188 }]

const initials = (name = 'User') => name.split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase()
const normalizeJob = (job = {}) => {
  const skills = Array.isArray(job.skills) ? job.skills.map((skill) => typeof skill === 'string' ? skill : skill.name).filter(Boolean) : []
  const salary = job.salaryMin || job.salaryMax ? `${job.salaryMin ? `$${Number(job.salaryMin).toLocaleString()}` : ''}${job.salaryMin && job.salaryMax ? ' – ' : ''}${job.salaryMax ? `$${Number(job.salaryMax).toLocaleString()}` : ''}` : 'Salary not specified'
  return { ...job, id: job.id, title: job.title || 'Untitled role', company: job.company || job.department || 'HireSense employer', location: job.location || 'Location not specified', type: job.type || (job.active === false ? 'Inactive' : 'Full-time'), salary, matchScore: job.matchScore ?? job.match ?? null, tags: skills }
}
const riskTone = (risk) => String(risk || '').toLowerCase() === 'high' ? 'red' : String(risk || '').toLowerCase() === 'medium' ? 'amber' : 'teal'
const riskLabel = (risk) => risk ? `${risk[0].toUpperCase()}${risk.slice(1).toLowerCase()}` : 'Unknown'
const score = (value) => value == null ? '—' : `${Math.round(Number(value))}%`
const arrayValue = (value) => Array.isArray(value) ? value : value ? [value] : []

function Toasts({ items, dismiss }) { return <div className="fixed right-4 top-4 z-[80] flex w-[min(360px,calc(100vw-2rem))] flex-col gap-2">{items.map((item) => <div key={item.id} className={cn('flex items-start gap-3 rounded-2xl border bg-white p-4 shadow-xl', item.type === 'error' ? 'border-red-200' : 'border-teal-100')}><div className={cn('mt-0.5 rounded-full p-1.5', item.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-teal-50 text-teal-600')}>{item.type === 'error' ? <CircleAlert size={15} /> : <Check size={15} />}</div><p className="flex-1 text-sm font-medium leading-5 text-slate-700">{item.message}</p><button onClick={() => dismiss(item.id)} className="text-slate-400 hover:text-slate-700"><X size={16} /></button></div>)}</div> }
export default function App() { const [toasts, setToasts] = useState([]); const notify = (message, type = 'success') => { const id = Date.now() + Math.random(); setToasts((value) => [...value, { id, message, type }]); setTimeout(() => setToasts((value) => value.filter((item) => item.id !== id)), 4500) }; return <ToastContext.Provider value={notify}><BrowserRouter><Routes><Route path="/login" element={<PublicRoute><Login /></PublicRoute>} /><Route path="/register" element={<PublicRoute><Register /></PublicRoute>} /><Route path="*" element={<ProtectedRoute><AppShell /></ProtectedRoute>} /></Routes></BrowserRouter><Toasts items={toasts} dismiss={(id) => setToasts((value) => value.filter((item) => item.id !== id))} /></ToastContext.Provider> }
function PublicRoute({ children }) { const { isAuthenticated, user } = useAuth(); if (isAuthenticated) return <Navigate to={user?.role === 'HR' ? '/hr' : user?.role === 'ADMIN' ? '/admin' : '/dashboard'} replace />; return children }
function ProtectedRoute({ children }) { const { isAuthenticated } = useAuth(); return isAuthenticated ? children : <Navigate to="/login" replace /> }
const navByRole = { CANDIDATE: [{ label: 'Overview', path: '/dashboard', icon: LayoutDashboard }, { label: 'My resume', path: '/resume', icon: FileText }, { label: 'Find jobs', path: '/jobs', icon: BriefcaseBusiness }, { label: 'Applications', path: '/applications', icon: ClipboardList }, { label: 'Match insights', path: '/match', icon: Target }], HR: [{ label: 'Overview', path: '/hr', icon: LayoutDashboard }, { label: 'Jobs', path: '/jobs', icon: BriefcaseBusiness }, { label: 'Candidates', path: '/candidates', icon: Users }, { label: 'Employees', path: '/employees', icon: ClipboardList }, { label: 'Attrition', path: '/attrition', icon: TrendingUp }], ADMIN: [{ label: 'Overview', path: '/admin', icon: LayoutDashboard }, { label: 'Users', path: '/admin/users', icon: Users }, { label: 'Activity', path: '/admin/activity', icon: Activity }, { label: 'System health', path: '/admin/health', icon: Activity }] }
function AppShell() { const { user, logout, isDemo } = useAuth(); const [mobileOpen, setMobileOpen] = useState(false); const location = useLocation(); const nav = navByRole[user?.role] || navByRole.CANDIDATE; const activeLabel = nav.find((item) => location.pathname === item.path || (item.path !== '/dashboard' && item.path !== '/hr' && location.pathname.startsWith(item.path)))?.label || 'Workspace'; return <div className="min-h-screen bg-[#f5f8fa]"><aside className={cn('fixed inset-y-0 left-0 z-50 flex w-[248px] flex-col border-r border-slate-200 bg-white px-4 py-5 transition-transform lg:translate-x-0', mobileOpen ? 'translate-x-0' : '-translate-x-full')}><div className="flex items-center gap-3 px-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#16324F] text-white"><Sparkles size={18} /></div><div><div className="font-display text-[15px] font-extrabold tracking-tight text-[#16324F]">HireSense <span className="text-[#0B8A84]">AI</span></div><div className="text-[10px] font-bold uppercase tracking-[.16em] text-slate-400">Talent intelligence</div></div></div><div className="mt-10 px-3"><span className="eyebrow">Workspace</span></div><nav className="mt-3 flex flex-1 flex-col gap-1">{nav.map(({ label, path, icon: Icon }) => <NavLink key={path} to={path} onClick={() => setMobileOpen(false)} className={({ isActive }) => cn('flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold transition', isActive ? 'bg-[#e8f5f3] text-[#0B6E6B]' : 'text-slate-500 hover:bg-slate-50 hover:text-[#16324F]')}><Icon size={17} />{label}</NavLink>)}<div className="my-4 border-t border-slate-100" /><NavLink to="/profile" onClick={() => setMobileOpen(false)} className={({ isActive }) => cn('flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold transition', isActive ? 'bg-[#e8f5f3] text-[#0B6E6B]' : 'text-slate-500 hover:bg-slate-50 hover:text-[#16324F]')}><UserRound size={17} />My profile</NavLink><NavLink to="/settings" onClick={() => setMobileOpen(false)} className="flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-slate-500 hover:bg-slate-50 hover:text-[#16324F]"><Settings size={17} />Settings</NavLink></nav><div className="rounded-2xl bg-[#f5f8fa] p-3"><div className="flex items-center gap-2.5"><Avatar name={user?.name} /><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold text-[#16324F]">{user?.name}</div><div className="truncate text-[11px] text-slate-400">{user?.title || user?.role}</div></div><button onClick={logout} title="Sign out" className="text-slate-400 hover:text-red-500"><LogOut size={15} /></button></div>{isDemo && <div className="mt-3 rounded-lg bg-amber-50 px-2.5 py-2 text-[10px] font-bold leading-4 text-amber-700">Demo-only sample workspace</div>}</div></aside>{mobileOpen && <button onClick={() => setMobileOpen(false)} className="fixed inset-0 z-40 bg-[#16324F]/30 lg:hidden" aria-label="Close navigation" />}<main className="min-h-screen lg:pl-[248px]"><header className="sticky top-0 z-30 flex h-[72px] items-center justify-between border-b border-slate-200/80 bg-[#f5f8fa]/90 px-5 backdrop-blur md:px-9"><div className="flex items-center gap-3"><button onClick={() => setMobileOpen(true)} className="rounded-lg p-2 text-slate-500 hover:bg-white lg:hidden"><Menu size={20} /></button><div><div className="eyebrow">{user?.role === 'CANDIDATE' ? 'Candidate workspace' : user?.role === 'HR' ? 'People operations' : 'Administration'}</div><div className="font-display mt-0.5 text-sm font-bold text-[#16324F]">{activeLabel}</div></div></div><div className="flex items-center gap-4"><div className={cn('hidden items-center gap-2 text-xs font-semibold sm:flex', isDemo ? 'text-amber-600' : 'text-slate-400')}><span className={cn('h-2 w-2 rounded-full', isDemo ? 'bg-amber-500' : 'bg-slate-300')} />{isDemo ? 'Demo workspace' : 'Live session'}</div><div className="h-8 w-px bg-slate-200" /><Link to="/profile" className="flex items-center gap-2"><Avatar name={user?.name} small /><span className="hidden text-sm font-bold text-[#16324F] md:block">{user?.name?.split(' ')[0]}</span><ChevronDown size={14} className="text-slate-400" /></Link></div></header><div className="mx-auto max-w-[1440px] p-5 md:p-9"><Routes><Route path="/" element={<Navigate to={user?.role === 'HR' ? '/hr' : user?.role === 'ADMIN' ? '/admin' : '/dashboard'} replace />} /><Route path="/dashboard" element={<CandidateDashboard />} /><Route path="/resume" element={<ResumeUpload />} /><Route path="/applications" element={<ApplicationsPage isDemo={isDemo} />} /><Route path="/match" element={<LiveMatchPage isDemo={isDemo} />} /><Route path="/jobs" element={<LiveJobListings isDemo={isDemo} userRole={user?.role} />} /><Route path="/jobs/new" element={<RoleRoute role="HR"><JobEditor /></RoleRoute>} /><Route path="/jobs/:id/edit" element={<RoleRoute role="HR"><JobEditor /></RoleRoute>} /><Route path="/hr" element={<RoleRoute role="HR"><HRDashboard /></RoleRoute>} /><Route path="/candidates" element={<RoleRoute role="HR"><LiveRankedCandidates isDemo={isDemo} /></RoleRoute>} /><Route path="/employees" element={<RoleRoute role="HR"><EmployeeList /></RoleRoute>} /><Route path="/employees/new" element={<RoleRoute role="HR"><EmployeeForm /></RoleRoute>} /><Route path="/attrition" element={<RoleRoute role="HR"><LiveAttritionDashboard isDemo={isDemo} /></RoleRoute>} /><Route path="/admin" element={<RoleRoute role="ADMIN"><AdminPanel /></RoleRoute>} /><Route path="/admin/users" element={<RoleRoute role="ADMIN"><LiveAdminUsers isDemo={isDemo} /></RoleRoute>} /><Route path="/admin/activity" element={<RoleRoute role="ADMIN"><LiveAdminActivity isDemo={isDemo} /></RoleRoute>} /><Route path="/admin/health" element={<RoleRoute role="ADMIN"><SystemHealth /></RoleRoute>} /><Route path="/profile" element={<Profile />} /><Route path="/settings" element={<SettingsPage />} /><Route path="*" element={<Navigate to="/" replace />} /></Routes></div></main></div> }
function RoleRoute({ role, children }) { const { user } = useAuth(); return user?.role === role ? children : <Navigate to="/" replace /> }
function Avatar({ name = 'User', small = false }) { return <div className={cn('grid shrink-0 place-items-center rounded-xl bg-[#dcefeb] font-bold text-[#0B6E6B]', small ? 'h-8 w-8 rounded-lg text-[10px]' : 'h-9 w-9 text-xs')}>{initials(name)}</div> }
function PageTitle({ eyebrow, title, description, actions }) { return <div className="mb-8 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="eyebrow">{eyebrow}</div><h1 className="font-display mt-1 text-2xl font-extrabold tracking-tight text-[#16324F] md:text-[30px]">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">{description}</p>}</div>{actions && <div className="flex flex-wrap gap-2">{actions}</div>}</div> }
function LoadingBlock({ label = 'Loading' }) { return <div className="card flex min-h-[170px] items-center justify-center gap-3 text-sm text-slate-400"><div className="h-5 w-5 animate-spin rounded-full border-2 border-slate-200 border-t-[#0B8A84]" />{label}</div> }
function ErrorNotice({ message, onRetry }) { return <div className="flex items-start gap-3 rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900"><CircleAlert size={18} className="mt-0.5 shrink-0 text-amber-600" /><div className="flex-1"><div className="font-bold">Live data is unavailable</div><div className="mt-1 text-amber-800/80">{message}</div></div>{onRetry && <button onClick={onRetry} className="text-xs font-bold text-amber-800 underline">Retry</button>}</div> }
function DemoNotice() { return <div className="mb-5 flex items-center gap-2 rounded-xl border border-amber-200 bg-amber-50 px-3 py-2 text-xs font-bold text-amber-800"><Zap size={14} />Demo-only sample data. Sign out and use a live account to view API data.</div> }
function EmptyState({ text = 'No records found.' }) { return <div className="card p-10 text-center text-sm text-slate-500">{text}</div> }
function StatCard({ label, value, detail, trend, icon: Icon, tone = 'teal' }) { return <div className="card p-5"><div className="flex items-start justify-between"><div><div className="text-xs font-bold text-slate-400">{label}</div><div className="font-display mt-2 text-2xl font-extrabold tracking-tight text-[#16324F]">{value}</div></div><div className={cn('rounded-xl p-2.5', tone === 'amber' ? 'bg-amber-50 text-amber-600' : tone === 'navy' ? 'bg-blue-50 text-[#16324F]' : 'bg-teal-50 text-[#0B8A84]')}><Icon size={18} /></div></div><div className="mt-4 flex items-center gap-2 text-xs"><span className="font-bold text-[#0B8A84]">{trend || 'Live'}</span><span className="text-slate-400">{detail}</span></div></div> }
function SectionHeader({ title, link, to }) { return <div className="mb-4 flex items-center justify-between"><h2 className="font-display text-base font-bold text-[#16324F]">{title}</h2>{link && <Link to={to || '#'} className="flex items-center gap-1 text-xs font-bold text-[#0B8A84] hover:text-[#16324F]">{link}<ArrowRight size={14} /></Link>}</div> }
function Tag({ children, tone = 'slate' }) { return <span className={cn('rounded-full px-2.5 py-1 text-[11px] font-bold', tone === 'teal' ? 'bg-teal-50 text-teal-700' : tone === 'red' ? 'bg-rose-50 text-rose-600' : tone === 'amber' ? 'bg-amber-50 text-amber-700' : 'bg-slate-100 text-slate-600')}>{children}</span> }
function Progress({ value = 0, color = '#0B8A84' }) { return <div className="h-2 overflow-hidden rounded-full bg-slate-100"><div style={{ width: `${Math.min(100, Math.max(0, Number(value) || 0))}%`, backgroundColor: color }} className="h-full rounded-full transition-all" /></div> }

function JobCard({ job, compact = false }) { const [saved, setSaved] = useState(false); const tags = job.tags || []; return <div className="card group p-5 transition hover:-translate-y-0.5 hover:border-teal-200"><div className="flex items-start gap-3"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-teal-100 text-lg font-extrabold text-teal-700">{(job.company || job.title || 'J')[0]}</div><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-3"><div><div className="font-display text-sm font-bold text-[#16324F]">{job.title}</div><div className="mt-1 text-xs text-slate-500">{job.company} · {job.location}</div></div><button onClick={() => setSaved(!saved)} className={cn('rounded-lg p-1.5', saved ? 'bg-teal-50 text-[#0B8A84]' : 'text-slate-300 hover:bg-slate-50 hover:text-slate-500')} aria-label={saved ? 'Remove saved job' : 'Save job'}>{saved ? <Check size={15} /> : <span className="text-lg leading-none">☆</span>}</button></div><div className="mt-3 flex flex-wrap items-center gap-2">{job.matchScore != null && <span className="rounded-lg bg-[#e8f5f3] px-2 py-1 text-xs font-extrabold text-[#0B6E6B]">{score(job.matchScore)} match</span>}<span className="text-xs text-slate-400">{job.type}</span><span className="text-xs text-slate-400">{job.salary}</span></div>{!compact && <div className="mt-4 flex flex-wrap gap-1.5">{tags.map((tag) => <Tag key={tag}>{tag}</Tag>)}</div>}</div></div></div> }
function CandidateDashboard() { const { user, isDemo } = useAuth(); const [jobs, setJobs] = useState(isDemo ? sampleJobs : []); const [loading, setLoading] = useState(!isDemo); const [error, setError] = useState(''); const load = async () => { if (isDemo) return; setLoading(true); setError(''); try { const { data } = await jobsApi.recommended(); setJobs(pageContent(data).map(normalizeJob)) } catch (e) { setError(apiError(e)) } finally { setLoading(false) } }; useEffect(() => { load() }, [isDemo]); return <><PageTitle eyebrow={`Good morning, ${user?.name?.split(' ')[0]}`} title="Your next opportunity starts here." description="A focused view of your profile strength, recommended roles, and the actions that move your search forward." actions={<Link to="/resume" className="btn-primary"><UploadCloud size={16} />Update resume</Link>} />{isDemo && <DemoNotice />}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Profile strength" value="—" detail="Live profile analysis" icon={Gauge} /><StatCard label="Best match" value={jobs[0]?.matchScore != null ? score(jobs[0].matchScore) : '—'} detail={jobs[0]?.title || 'No recommendation yet'} trend="Live" icon={Target} tone="navy" /><StatCard label="Profile views" value="—" detail="Not exposed by API" icon={Users} /><StatCard label="Applications" value="—" detail="Not exposed by API" icon={BriefcaseBusiness} tone="amber" /></div><div className="mt-8 grid gap-6 xl:grid-cols-[1.45fr_1fr]"><div><SectionHeader title="Recommended for you" link="View all jobs" to="/jobs" />{error && <div className="mb-4"><ErrorNotice message={error} onRetry={load} /></div>}{loading ? <LoadingBlock label="Finding roles that fit your profile" /> : jobs.length ? <div className="space-y-3">{jobs.slice(0, 3).map((job) => <JobCard key={job.id} job={job} compact />)}</div> : <EmptyState text="No recommended jobs are available yet." />}</div><div className="card overflow-hidden"><div className="border-b border-slate-100 p-5"><SectionHeader title="Profile readiness" link="Improve" to="/profile" /><p className="text-sm leading-6 text-slate-500">Live readiness metrics appear when your profile is analyzed.</p></div><div className="space-y-5 p-5"><Readiness label="Resume completeness" value={null} /><Readiness label="Skills coverage" value={null} /><Readiness label="Work preferences" value={null} /><div className="rounded-xl bg-[#f5f8fa] p-3 text-xs leading-5 text-slate-500"><Sparkles size={14} className="mb-1 text-[#E9A23B]" />Upload a resume and complete your profile to unlock match insights.</div></div></div></div></> }
function Readiness({ label, value }) { return <div><div className="mb-2 flex justify-between text-xs"><span className="font-bold text-slate-600">{label}</span><span className="font-bold text-[#16324F]">{value == null ? '—' : `${value}%`}</span></div><Progress value={value || 0} /></div> }
function ResumeUpload() { const notify = useToast(); const { isDemo } = useAuth(); const [file, setFile] = useState(null); const [latest, setLatest] = useState(null); const [drag, setDrag] = useState(false); const [loading, setLoading] = useState(false); const input = useRef(); const choose = (selected) => { if (!selected) return; const valid = ['application/pdf', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'].includes(selected.type) || /\.(pdf|docx)$/i.test(selected.name); if (!valid) return notify('Please select a PDF or DOCX resume.', 'error'); if (selected.size > 5 * 1024 * 1024) return notify('Resume files must be 5 MB or smaller.', 'error'); setFile(selected) }; const upload = async () => { if (!file) return; if (isDemo) return notify('Resume upload is disabled in demo-only sample workspace.', 'error'); setLoading(true); try { const { data } = await resumeApi.upload(file); setLatest(data); if (data.id != null) localStorage.setItem('hiresense_latest_resume_id', String(data.id)); notify(`Resume uploaded: ${data.fileName || file.name}.`) } catch (e) { notify(apiError(e), 'error') } finally { setLoading(false) } }; return <><PageTitle eyebrow="Profile foundation" title="Keep your resume current." description="Upload the resume you want HireSense to use when scoring your profile against opportunities." />{isDemo && <DemoNotice />}<div className="grid gap-6 lg:grid-cols-[1.4fr_0.8fr]"><div className="card p-6 md:p-8"><div onDragOver={(e) => { e.preventDefault(); setDrag(true) }} onDragLeave={() => setDrag(false)} onDrop={(e) => { e.preventDefault(); setDrag(false); choose(e.dataTransfer.files?.[0]) }} onClick={() => input.current?.click()} className={cn('flex min-h-[300px] cursor-pointer flex-col items-center justify-center rounded-2xl border-2 border-dashed px-6 text-center transition', drag ? 'border-[#0B8A84] bg-teal-50' : 'border-slate-200 bg-[#fbfcfd] hover:border-[#0B8A84] hover:bg-teal-50/40')}><input ref={input} type="file" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" className="hidden" onChange={(e) => choose(e.target.files?.[0])} /><div className="mb-4 grid h-14 w-14 place-items-center rounded-2xl bg-[#e8f5f3] text-[#0B8A84]"><UploadCloud size={25} /></div><div className="font-display text-base font-bold text-[#16324F]">Drop your resume here</div><div className="mt-2 text-sm text-slate-400">or click to browse from your device</div><div className="mt-5 text-xs font-bold text-slate-400">PDF or DOCX · Up to 5 MB</div></div>{file && <div className="mt-4 flex items-center gap-3 rounded-xl border border-teal-100 bg-teal-50/60 p-3"><FileText size={18} className="text-[#0B8A84]" /><div className="min-w-0 flex-1"><div className="truncate text-sm font-bold text-[#16324F]">{file.name}</div><div className="text-xs text-slate-400">{(file.size / 1024 / 1024).toFixed(2)} MB ready to upload</div></div><button onClick={() => setFile(null)} className="text-slate-400 hover:text-red-500"><X size={16} /></button></div>}<button disabled={!file || loading || isDemo} onClick={upload} className="btn-primary mt-5 w-full">{loading ? 'Uploading…' : isDemo ? 'Upload unavailable in demo' : 'Upload resume'}</button>{latest && <div className="mt-4 rounded-xl bg-teal-50 p-3 text-xs text-teal-800">Latest upload: <b>{latest.fileName || file?.name}</b> · status {latest.status || 'received'} · resume ID {latest.id}</div>}</div><div className="space-y-4"><div className="card p-5"><div className="flex items-center gap-2"><ShieldCheck size={18} className="text-[#0B8A84]" /><h2 className="font-display text-sm font-bold text-[#16324F]">Your data, in your control</h2></div><p className="mt-3 text-sm leading-6 text-slate-500">Resume files are stored in service-controlled storage and accessed through authenticated APIs. Enable HTTPS and encrypted storage volumes for deployment.</p></div><div className="card p-5"><div className="eyebrow">Latest resume</div><div className="mt-3 text-sm font-bold text-[#16324F]">{latest?.fileName || 'No resume uploaded in this session'}</div><div className="mt-1 text-xs text-slate-400">{latest ? `Status: ${latest.status || 'received'}` : 'Upload a PDF or DOCX to begin.'}</div></div></div></div></> }
function MatchResult() { const { isDemo } = useAuth(); const notify = useToast(); const [resumes, setResumes] = useState([]); const [jobs, setJobs] = useState(isDemo ? sampleJobs : []); const [resumeId, setResumeId] = useState(localStorage.getItem('hiresense_latest_resume_id') || ''); const [jobId, setJobId] = useState(isDemo ? sampleJobs[0].id : ''); const [result, setResult] = useState(null); const [loading, setLoading] = useState(!isDemo); const [error, setError] = useState(''); useEffect(() => { if (isDemo) return; Promise.all([resumeApi.list(), jobsApi.list()]).then(([resumeResponse, jobResponse]) => { const resumeRows = pageContent(resumeResponse.data); const jobRows = pageContent(jobResponse.data).map(normalizeJob); setResumes(resumeRows); setJobs(jobRows); setResumeId((current) => current || String(resumeRows[0]?.id || '')); setJobId((current) => current || String(jobRows[0]?.id || '')) }).catch((e) => setError(apiError(e))).finally(() => setLoading(false)) }, [isDemo]); const runMatch = async () => { if (isDemo) return notify('Match analysis is a demo-only sample. Select a live account to call the backend.', 'error'); if (!resumeId || !jobId) return notify('Select a resume and job before running an analysis.', 'error'); setLoading(true); try { const { data } = await matchApi.calculate({ resumeId, jobId }); setResult(data); notify('Match analysis refreshed.') } catch (e) { notify(apiError(e), 'error') } finally { setLoading(false) } }; const active = result || (isDemo ? { overallScore: 94, semanticScore: 98, skillScore: 98, experienceScore: 92, educationScore: 88, matchedSkills: ['Figma', 'Design systems', 'User research', 'Prototyping'], missingSkills: ['SQL', 'Motion design'] } : null); return <><PageTitle eyebrow="Match insights" title="Understand your fit." description="Choose a real resume and job to run the backend match analysis." actions={<button onClick={runMatch} disabled={loading || isDemo} className="btn-secondary"><Sparkles size={16} />{loading ? 'Refreshing…' : isDemo ? 'Demo analysis' : 'Run analysis'}</button>} />{isDemo && <DemoNotice />}{error && <div className="mb-5"><ErrorNotice message={error} /></div>}<div className="mb-6 grid gap-4 md:grid-cols-2"><div><label className="label">Resume</label><select className="input" value={resumeId} onChange={(e) => setResumeId(e.target.value)} disabled={isDemo || loading}><option value="">Select resume</option>{resumes.map((resume) => <option key={resume.id} value={resume.id}>{resume.fileName || `Resume ${resume.id}`} · {resume.id}</option>)}{isDemo && <option value="sample-001">Demo resume · sample-001</option>}</select></div><div><label className="label">Job</label><select className="input" value={jobId} onChange={(e) => setJobId(e.target.value)} disabled={isDemo || loading}><option value="">Select job</option>{jobs.map((job) => <option key={job.id} value={job.id}>{job.title} · {job.id}</option>)}</select></div></div>{!active ? <EmptyState text="Run an analysis to see match insights." /> : <div className="grid gap-6 xl:grid-cols-[0.85fr_1.5fr]"><div className="card flex flex-col items-center justify-center p-8 text-center"><div className="eyebrow">Overall match</div><div className="relative mt-6 h-52 w-52"><svg viewBox="0 0 220 220" className="h-full w-full -rotate-90"><circle cx="110" cy="110" r="88" fill="none" stroke="#e7eef1" strokeWidth="16" /><circle cx="110" cy="110" r="88" fill="none" stroke="#0B8A84" strokeWidth="16" strokeLinecap="round" strokeDasharray="553" strokeDashoffset={553 - (553 * Number(active.overallScore || 0) / 100)} /></svg><div className="absolute inset-0 flex flex-col items-center justify-center"><div className="font-display text-5xl font-extrabold tracking-tight text-[#16324F]">{score(active.overallScore)}</div><div className="mt-1 text-xs font-bold text-[#0B6E6B]">{Number(active.overallScore || 0) >= 80 ? 'Excellent fit' : 'Room to grow'}</div></div></div><p className="mt-5 max-w-xs text-sm leading-6 text-slate-500">The score is calculated from the selected resume and job by the HireSense match engine.</p></div><div className="space-y-6"><div className="card p-6"><SectionHeader title="Match breakdown" /><div className="space-y-5"><MatchBar label="Semantic fit" value={active.semanticScore} /><MatchBar label="Core skills" value={active.skillScore} /><MatchBar label="Relevant experience" value={active.experienceScore} /><MatchBar label="Education" value={active.educationScore} /></div></div><div className="grid gap-6 md:grid-cols-2"><SkillPanel title="Matched skills" skills={active.matchedSkills || []} tone="teal" /><SkillPanel title="Skills to strengthen" skills={active.missingSkills || []} tone="red" /></div></div></div>} {active?.improvementTips?.length > 0 && <div className="mt-6 card p-6"><SectionHeader title="Improvement tips" /><ul className="list-disc space-y-2 pl-5 text-sm leading-6 text-slate-500">{active.improvementTips.map((tip) => <li key={tip}>{tip}</li>)}</ul></div>}</> }
function MatchBar({ label, value }) { return <div><div className="mb-2 flex justify-between"><span className="text-sm font-bold text-slate-600">{label}</span><span className="text-xs font-extrabold text-[#16324F]">{score(value)}</span></div><Progress value={value || 0} /></div> }
function SkillPanel({ title, skills, tone }) { return <div className="card p-5"><div className="flex items-center gap-2"><div className={cn('grid h-7 w-7 place-items-center rounded-lg', tone === 'teal' ? 'bg-teal-50 text-[#0B8A84]' : 'bg-rose-50 text-rose-500')}>{tone === 'teal' ? <Check size={14} /> : <Target size={14} />}</div><h3 className="font-display text-sm font-bold text-[#16324F]">{title}</h3></div><div className="mt-4 flex flex-wrap gap-2">{skills.length ? skills.map((skill) => <Tag key={skill} tone={tone}>{skill}</Tag>) : <span className="text-sm text-slate-400">None returned</span>}</div></div> }
function JobListings() { const { user, isDemo } = useAuth(); const [jobs, setJobs] = useState(isDemo ? sampleJobs : []); const [search, setSearch] = useState(''); const [loading, setLoading] = useState(!isDemo); const [error, setError] = useState(''); const [filter, setFilter] = useState('All roles'); const load = async () => { if (isDemo) return; setLoading(true); setError(''); try { const { data } = await jobsApi.list(); setJobs(pageContent(data).map(normalizeJob)) } catch (e) { setError(apiError(e)) } finally { setLoading(false) } }; useEffect(() => { load() }, [isDemo]); const filtered = jobs.filter((job) => `${job.title} ${job.company} ${job.location}`.toLowerCase().includes(search.toLowerCase()) && (filter === 'All roles' || job.type === filter)); return <><PageTitle eyebrow="Opportunities" title={user?.role === 'HR' ? 'Jobs at a glance.' : 'Roles matched to your ambition.'} description={user?.role === 'HR' ? 'Create, review, and manage the roles your team is hiring for.' : 'Discover roles where your experience can make an immediate impact.'} actions={user?.role === 'HR' && <Link to="/jobs/new" className="btn-primary"><BriefcaseBusiness size={16} />Create a job</Link>} />{isDemo && <DemoNotice />}<div className="mb-6 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search size={17} className="absolute left-3.5 top-3.5 text-slate-400" /><input className="input mt-0 pl-10" aria-label="Search roles" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search by title or location" /></div><select className="input mt-0 sm:w-44" value={filter} onChange={(e) => setFilter(e.target.value)} aria-label="Filter roles"><option>All roles</option><option>Full-time</option><option>Contract</option></select></div>{error && <div className="mb-5"><ErrorNotice message={error} onRetry={load} /></div>}{loading ? <LoadingBlock label="Loading open roles" /> : filtered.length ? <div className="grid gap-4 lg:grid-cols-2">{filtered.map((job) => <div key={job.id}><JobCard job={job} />{user?.role === 'HR' && <div className="-mt-2 flex justify-end gap-2 rounded-b-2xl border border-t-0 border-slate-200/80 bg-white px-5 pb-4"><Link to={`/jobs/${job.id}/edit`} className="text-xs font-bold text-[#0B8A84]">Edit role</Link><Link to={`/candidates?job=${job.id}`} className="text-xs font-bold text-slate-400">View candidates</Link></div>}</div>)}</div> : <EmptyState text="No roles match your current filters." />}</> }
function JobEditor() {
  const { id } = useParams()
  const notify = useToast()
  const navigate = useNavigate()
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [form, setForm] = useState({ title: '', description: '', minExperienceYears: '', educationLevel: '', salaryMin: '', salaryMax: '', location: '', active: true, requiredSkills: '', preferredSkills: '' })
  const set = (key, value) => setForm((current) => ({ ...current, [key]: value }))
  useEffect(() => {
    if (!id) return
    setLoading(true)
    jobsApi.get(id).then(({ data }) => {
      const skills = Array.isArray(data.skills) ? data.skills : []
      setForm({ title: data.title || '', description: data.description || '', minExperienceYears: data.minExperienceYears ?? '', educationLevel: data.educationLevel || '', salaryMin: data.salaryMin ?? '', salaryMax: data.salaryMax ?? '', location: data.location || '', active: Boolean(data.active), requiredSkills: skills.filter((item) => item.type === 'REQUIRED').map((item) => item.name).join(', '), preferredSkills: skills.filter((item) => item.type === 'PREFERRED').map((item) => item.name).join(', ') })
    }).catch((loadError) => setError(apiError(loadError))).finally(() => setLoading(false))
  }, [id])
  const names = (value) => value.split(',').map((name) => name.trim()).filter(Boolean)
  const save = async (event) => {
    event.preventDefault()
    setLoading(true)
    setError('')
    const payload = { title: form.title, description: form.description, minExperienceYears: form.minExperienceYears === '' ? null : Number(form.minExperienceYears), educationLevel: form.educationLevel || null, salaryMin: form.salaryMin === '' ? null : Number(form.salaryMin), salaryMax: form.salaryMax === '' ? null : Number(form.salaryMax), location: form.location || null, active: form.active, requiredSkills: names(form.requiredSkills), preferredSkills: names(form.preferredSkills) }
    try {
      if (id) await jobsApi.update(id, payload)
      else await jobsApi.create(payload)
      notify(id ? 'Job updated successfully.' : 'Job created and ready for candidates.')
      navigate('/jobs')
    } catch (saveError) { setError(apiError(saveError)); notify(apiError(saveError), 'error') }
    finally { setLoading(false) }
  }
  const remove = async () => {
    if (!id || !window.confirm('Deactivate this job posting? It will no longer appear to candidates.')) return
    setLoading(true)
    try { await jobsApi.delete(id); notify('Job deactivated.'); navigate('/jobs') }
    catch (deleteError) { setError(apiError(deleteError)); notify(apiError(deleteError), 'error') }
    finally { setLoading(false) }
  }
  return <><PageTitle eyebrow={id ? 'Edit role' : 'New opportunity'} title={id ? 'Refine this role.' : 'Create a role.'} description="Set clear job criteria; required and preferred skills are saved separately for matching." />{error && <ErrorNotice message={error} />}{loading && id && !form.title ? <LoadingBlock label="Loading job" /> : <form onSubmit={save} className="card max-w-3xl space-y-5 p-6"><div><label className="label">Title</label><input required maxLength="180" className="input" value={form.title} onChange={(event) => set('title', event.target.value)} /></div><div><label className="label">Description</label><textarea required rows="5" maxLength="50000" className="input resize-none" value={form.description} onChange={(event) => set('description', event.target.value)} /></div><div className="grid gap-5 md:grid-cols-2"><div><label className="label">Location</label><input maxLength="160" className="input" value={form.location} onChange={(event) => set('location', event.target.value)} /></div><div><label className="label">Education level</label><input maxLength="120" className="input" value={form.educationLevel} onChange={(event) => set('educationLevel', event.target.value)} /></div><div><label className="label">Minimum experience (years)</label><input type="number" min="0" step="0.1" className="input" value={form.minExperienceYears} onChange={(event) => set('minExperienceYears', event.target.value)} /></div><div><label className="label">Salary range</label><div className="flex gap-2"><input type="number" min="0" placeholder="Min" className="input" value={form.salaryMin} onChange={(event) => set('salaryMin', event.target.value)} /><input type="number" min="0" placeholder="Max" className="input" value={form.salaryMax} onChange={(event) => set('salaryMax', event.target.value)} /></div></div></div><div><label className="label">Required skills (comma separated)</label><input className="input" value={form.requiredSkills} onChange={(event) => set('requiredSkills', event.target.value)} placeholder="Java, SQL, Spring Boot" /></div><div><label className="label">Preferred skills (comma separated)</label><input className="input" value={form.preferredSkills} onChange={(event) => set('preferredSkills', event.target.value)} placeholder="Docker, Kubernetes" /></div><label className="flex items-center gap-2 text-sm font-semibold text-slate-600"><input type="checkbox" checked={form.active} onChange={(event) => set('active', event.target.checked)} /> Active and visible to candidates</label><div className="flex justify-between gap-2 border-t border-slate-100 pt-5"><div>{id && <button type="button" onClick={remove} disabled={loading} className="btn-secondary text-red-600">Deactivate job</button>}</div><div className="flex gap-2"><button type="button" onClick={() => navigate('/jobs')} className="btn-secondary">Cancel</button><button disabled={loading} className="btn-primary">{loading ? 'Saving…' : 'Save role'}</button></div></div></form>}</>
}
function HRDashboard() { const { isDemo } = useAuth(); const [employees, setEmployees] = useState(isDemo ? sampleEmployees : []); const [loading, setLoading] = useState(!isDemo); const [error, setError] = useState(''); useEffect(() => { if (isDemo) return; employeesApi.list().then(({ data }) => setEmployees(pageContent(data))).catch((e) => setError(apiError(e))).finally(() => setLoading(false)) }, [isDemo]); const high = employees.filter((employee) => String(employee.riskLevel || '').toLowerCase() === 'high'); return <><PageTitle eyebrow="People operations" title="A clearer view of your workforce." description="Review hiring activity and employee risk from live HR data." actions={<Link to="/employees/new" className="btn-primary"><Users size={16} />Add employee</Link>} />{isDemo && <DemoNotice />}{error && <div className="mb-5"><ErrorNotice message={error} /></div>}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Employees" value={loading ? '…' : employees.length} detail="Current directory" icon={Users} /><StatCard label="High risk" value={loading ? '…' : high.length} detail="Needs attention" trend="Live" icon={CircleAlert} tone="amber" /><StatCard label="Open roles" value="—" detail="See jobs for live count" icon={BriefcaseBusiness} /><StatCard label="Match analyses" value="—" detail="Not exposed by API" icon={Target} tone="navy" /></div><div className="mt-8 grid gap-6 xl:grid-cols-[1.35fr_1fr]"><div><SectionHeader title="Workforce trend" /><div className="card p-5"><div className="h-[260px]">{isDemo ? <ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e8eef1" /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 11 }} /><Tooltip /><Area type="monotone" dataKey="apps" stroke="#0B8A84" fill="#dff2ef" strokeWidth={3} /></AreaChart></ResponsiveContainer> : <div className="flex h-full items-center justify-center text-sm text-slate-400">Trend history is not exposed by the current API.</div>}</div></div></div><div><SectionHeader title="Risk watchlist" link="Open directory" to="/employees" />{loading ? <LoadingBlock label="Loading employees" /> : high.length ? <div className="card divide-y divide-slate-100">{high.slice(0, 4).map((employee) => <div key={employee.id} className="flex items-center gap-3 p-4"><Avatar name={employee.fullName} /><div className="min-w-0 flex-1"><div className="truncate text-sm font-bold text-[#16324F]">{employee.fullName}</div><div className="mt-1 truncate text-xs text-slate-400">{employee.department} · {employee.jobRole}</div></div><Tag tone={riskTone(employee.riskLevel)}>{riskLabel(employee.riskLevel)} · {score(employee.probability)}</Tag></div>)}</div> : <EmptyState text="No high-risk employees returned." />}</div></div></> }
function EmployeeList() { const { isDemo } = useAuth(); const notify = useToast(); const [employees, setEmployees] = useState(isDemo ? sampleEmployees : []); const [loading, setLoading] = useState(!isDemo); const [error, setError] = useState(''); const [search, setSearch] = useState(''); const input = useRef(); const load = async () => { if (isDemo) return; setLoading(true); setError(''); try { const { data } = await employeesApi.list(); setEmployees(pageContent(data)) } catch (e) { setError(apiError(e)) } finally { setLoading(false) } }; useEffect(() => { load() }, [isDemo]); const filtered = employees.filter((employee) => `${employee.fullName} ${employee.department} ${employee.jobRole} ${employee.email}`.toLowerCase().includes(search.toLowerCase())); const importCsv = async (file) => { if (!file) return; if (isDemo) return notify('Employee import is disabled in demo-only sample workspace.', 'error'); try { await employeesApi.import(file); notify('Employee CSV imported.'); load() } catch (e) { notify(apiError(e), 'error') } }; return <><PageTitle eyebrow="People directory" title="Every employee, in context." description="Search employee records and import the latest CSV from your HR system." actions={<><input ref={input} type="file" accept=".csv,text/csv" className="hidden" onChange={(e) => importCsv(e.target.files?.[0])} /><button onClick={() => input.current?.click()} className="btn-secondary"><UploadCloud size={16} />Import CSV</button><Link to="/employees/new" className="btn-primary"><Users size={16} />Add employee</Link></>} />{isDemo && <DemoNotice />}<div className="mb-5 relative"><Search size={17} className="absolute left-3.5 top-3.5 text-slate-400" /><input className="input mt-0 pl-10" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search name, department, or role" /></div>{error && <div className="mb-5"><ErrorNotice message={error} onRetry={load} /></div>}{loading ? <LoadingBlock label="Loading employee directory" /> : <div className="card overflow-hidden">{filtered.length ? filtered.map((employee) => <div key={employee.id} className="flex flex-wrap items-center gap-3 border-b border-slate-100 p-4 last:border-0"><Avatar name={employee.fullName} /><div className="min-w-[180px] flex-1"><div className="text-sm font-bold text-[#16324F]">{employee.fullName || 'Unnamed employee'}</div><div className="mt-1 text-xs text-slate-400">{employee.email || 'No email'}</div></div><div className="min-w-[150px] text-sm text-slate-600"><div>{employee.department || '—'}</div><div className="mt-1 text-xs text-slate-400">{employee.jobRole || '—'}</div></div><div className="text-sm text-slate-500">{employee.yearsAtCompany != null ? `${employee.yearsAtCompany} yrs` : '—'}</div><Tag tone={riskTone(employee.riskLevel)}>{riskLabel(employee.riskLevel)}{employee.probability != null ? ` · ${score(employee.probability)}` : ''}</Tag><MoreHorizontal size={18} className="text-slate-400" /></div>) : <EmptyState text="No employees match your search." />}</div>}</> }
